FEN = "rnbqkbnr/pppp1ppp/8/4p3/4P3/8/PPPP1PPP/RNBQKBNR w KQkq - 0 2"

PIECES = {'P':100,'N':320,'B':330,'R':500,'Q':900,'K':0}
CENTER = {(4,3),(4,4),(5,3),(5,4)}  # ranks 4,5; files d,e

def parse_board(fen):
    rows = fen.split()[0].split('/')
    b = {}
    for i, row in enumerate(rows):
        rank = 8 - i
        file = 0
        for ch in row:
            if ch.isdigit():
                file += int(ch)
            else:
                b[(rank, file)] = ch
                file += 1
    return b

def side_to_move(fen):
    return fen.split()[1]

def attacks_square(b, attacker_is_white, target):
    tr, tf = target
    enemy = 'PNBRQK' if attacker_is_white else 'pnbrqk'
    # pawns
    if attacker_is_white:
        for df in (-1, 1):
            if b.get((tr-1, tf-df)) == 'P':  # equivalent to pawn at r-1, f+df? see below
                return True
    else:
        for df in (-1, 1):
            if b.get((tr+1, tf-df)) == 'p':
                return True
    # knights
    for dr, df in ((1,2),(1,-2),(-1,2),(-1,-2),(2,1),(2,-1),(-2,1),(-2,-1)):
        p = b.get((tr+dr, tf+df))
        if p in ('N' if attacker_is_white else 'n',):
            return True
    # king
    for dr in (-1,0,1):
        for df in (-1,0,1):
            if dr == 0 and df == 0:
                continue
            p = b.get((tr+dr, tf+df))
            if p == ('K' if attacker_is_white else 'k'):
                return True
    # sliders
    diag = ((1,1),(1,-1),(-1,1),(-1,-1))
    orth = ((1,0),(-1,0),(0,1),(0,-1))
    bishops = ('B','Q') if attacker_is_white else ('b','q')
    rooks = ('R','Q') if attacker_is_white else ('r','q')
    for directions, pieces in ((diag, bishops), (orth, rooks)):
        for dr, df in directions:
            r, f = tr+dr, tf+df
            while 1 <= r <= 8 and 0 <= f <= 7:
                p = b.get((r,f))
                if p:
                    if p in pieces:
                        return True
                    break
                r += dr; f += df
    return False

def in_check(fen, b=None):
    if b is None:
        b = parse_board(fen)
    stm = side_to_move(fen)
    king = 'K' if stm == 'w' else 'k'
    loc = None
    for sq, p in b.items():
        if p == king:
            loc = sq
            break
    if loc is None:
        return False
    return attacks_square(b, stm == 'b', loc)  # enemy is white iff black to move

def terminal_score(res):
    if not res.get('game_over'):
        return None
    w = str(res.get('winner', '') or '').lower()
    result = str(res.get('result', '') or '')
    if w == 'white' or result == '1-0':
        return 100000
    if w == 'black' or result == '0-1':
        return -100000
    return 0

def evaluate(fen, res=None):
    if res is None:
        res = simulate_move(fen)
    ts = terminal_score(res)
    if ts is not None:
        return ts
    b = parse_board(fen)
    score = 0
    for (r,f), p in b.items():
        v = PIECES[p.upper()]
        if p.isupper():
            score += v
        else:
            score -= v
        if (r,f) in CENTER:
            score += 12 if p.isupper() else -12
    if in_check(fen, b):
        score += -25 if side_to_move(fen) == 'w' else 25
    return score

root = simulate_move(FEN)
legal = sorted(root['legal_moves'])
best_move = None
best_score = None
rows = []
for mv in legal:
    after = simulate_move(FEN, mv)
    tscore = terminal_score(after)
    if tscore is not None:
        score = tscore
        reply_count = 0
    else:
        replies = sorted(after['legal_moves'])
        reply_count = len(replies)
        if not replies:
            # Should normally be terminal; defensive handling
            score = evaluate(after['fen'], after)
        else:
            score = None
            for rep in replies:
                final = simulate_move(after['fen'], rep)
                s = evaluate(final['fen'], final)
                if score is None or s < score:
                    score = s
    rows.append((mv, score, reply_count))
    if best_score is None or score > best_score:
        best_score = score
        best_move = mv

print("root legal:", len(legal))
for mv, s, rc in rows:
    print(f"{mv} {s} replies={rc}")
print("BEST", best_move, best_score)
play_move(best_move)
