        for dr, df in directions:
            r, f = tr+dr, tf+df
            while 1 <= r <= 8 and 0 <= f <= 7:
                p = b.get((r,f))
                if p:
                    if p in pieces:
                        return True
                    break
                r += dr; f += df
    return False

def in_check(fen, b=None):
    if b is None:
