def side_to_move(fen):
    return fen.split()[1]

def attacks_square(b, attacker_is_white, target):
    tr, tf = target
    enemy = 'PNBRQK' if attacker_is_white else 'pnbrqk'
    # pawns
    if attacker_is_white:
        for df in (-1, 1):
            if b.get((tr-1, tf-df)) == 'P':  # equivalent to pawn at r-1, f+df? see below
                return True
    else:
        for df in (-1, 1):
            if b.get((tr+1, tf-df)) == 'p':
                return True
    # knights
    for dr, df in ((1,2),(1,-2),(-1,2),(-1,-2),(2,1),(2,-1),(-2,1),(-2,-1)):
        p = b.get((tr+dr, tf+df))
        if p in ('N' if attacker_is_white else 'n',):
            return True
